CREATE DATABASE IF NOT EXISTS `mp3_nativedb`;
USE `mp3_nativedb`;

DROP TABLE IF EXISTS `natives`;
DROP TABLE IF EXISTS `namespaces`;

CREATE TABLE `namespaces` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(100) NOT NULL UNIQUE,
  `native_count` INT DEFAULT 0,
  PRIMARY KEY (`id`),
  INDEX `idx_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `natives` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `namespace_id` INT NOT NULL,
  `hash` VARCHAR(66) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `return_type` VARCHAR(50) DEFAULT NULL,
  `params` JSON DEFAULT NULL,
  `comment` TEXT DEFAULT NULL,
  `build` VARCHAR(20) DEFAULT NULL,
  `gta_hash` VARCHAR(66) DEFAULT NULL,
  `gta_jhash` VARCHAR(66) DEFAULT NULL,
  `unused` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  INDEX `idx_namespace_id` (`namespace_id`),
  INDEX `idx_name` (`name`),
  INDEX `idx_hash` (`hash`),
  UNIQUE KEY `unique_native` (`namespace_id`, `name`),
  FOREIGN KEY (`namespace_id`) REFERENCES `namespaces`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

